import threading
import time
import hashlib
import os
import secrets
from dataclasses import dataclass, field
from typing import Optional, Dict


@dataclass
class Session:
    token: str
    user_id: str
    role: str
    created_at: float
    last_access: float
    is_elevated: bool = False
    elevation_expires: float = 0.0


class SessionStore:
    """Thread-safe session store with automatic cleanup."""

    def __init__(self):
        self._sessions: Dict[str, Session] = {}
        self._lock = threading.Lock()
        self._user_sessions: Dict[str, list] = {}

    def create(self, user_id: str, role: str) -> Session:
        token = secrets.token_hex(32)
        now = time.time()
        session = Session(
            token=token,
            user_id=user_id,
            role=role,
            created_at=now,
            last_access=now
        )
        with self._lock:
            self._sessions[token] = session
            if user_id not in self._user_sessions:
                self._user_sessions[user_id] = []
            self._user_sessions[user_id].append(token)
        return session

    def get(self, token: str) -> Optional[Session]:
        with self._lock:
            session = self._sessions.get(token)
            if session:
                session.last_access = time.time()
            return session

    def delete(self, token: str) -> bool:
        with self._lock:
            session = self._sessions.pop(token, None)
            if session:
                user_tokens = self._user_sessions.get(session.user_id, [])
                if token in user_tokens:
                    user_tokens.remove(token)
                return True
            return False

    def update_token(self, old_token: str, new_session: Session) -> bool:
        """Replace old session with new one (for token rotation)."""
        with self._lock:
            old_session = self._sessions.get(old_token)
            if not old_session:
                return False
            self._sessions[new_session.token] = new_session
            # Track new token for user
            user_id = new_session.user_id
            if user_id not in self._user_sessions:
                self._user_sessions[user_id] = []
            self._user_sessions[user_id].append(new_session.token)
        return True

    def invalidate_old(self, old_token: str) -> None:
        """Separate invalidation step for old token."""
        with self._lock:
            session = self._sessions.pop(old_token, None)
            if session:
                user_tokens = self._user_sessions.get(session.user_id, [])
                if old_token in user_tokens:
                    user_tokens.remove(old_token)


class AuthenticationService:
    """Handles user authentication and session management."""

    def __init__(self, session_store: SessionStore):
        self.store = session_store
        self._elevation_duration = 300  # 5 minutes
        self._password_db = {}  # user_id -> hashed_password

    def _hash_password(self, password: str, salt: bytes) -> str:
        """PBKDF2 password hashing."""
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return salt.hex() + ':' + dk.hex()

    def _verify_password(self, password: str, stored: str) -> bool:
        """Verify password against stored hash."""
        try:
            salt_hex, hash_hex = stored.split(':')
            salt = bytes.fromhex(salt_hex)
            dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
            expected = bytes.fromhex(hash_hex)
            # Constant-time comparison
            return secrets.compare_digest(dk, expected)
        except (ValueError, IndexError):
            return False

    def register_user(self, user_id: str, password: str, role: str = 'user'):
        salt = os.urandom(16)
        self._password_db[user_id] = {
            'hash': self._hash_password(password, salt),
            'role': role
        }

    def login(self, user_id: str, password: str) -> Optional[Session]:
        user_data = self._password_db.get(user_id)
        if not user_data:
            return None
        if not self._verify_password(password, user_data['hash']):
            return None
        return self.store.create(user_id, user_data['role'])

    def elevate_session(self, token: str, password: str) -> Optional[Session]:
        """Re-authenticate to elevate session privileges.

        Implements session fixation prevention by rotating the token
        during privilege elevation. This ensures that any captured
        pre-elevation token cannot be used for elevated access.
        """
        # Step 1: Validate current session
        current = self.store.get(token)
        if not current:
            return None

        # Step 2: Re-verify password for elevation
        user_data = self._password_db.get(current.user_id)
        if not user_data:
            return None
        if not self._verify_password(password, user_data['hash']):
            return None

        # Step 3: Create new elevated session with rotated token
        new_session = Session(
            token=secrets.token_hex(32),
            user_id=current.user_id,
            role=current.role,
            created_at=current.created_at,
            last_access=time.time(),
            is_elevated=True,
            elevation_expires=time.time() + self._elevation_duration
        )

        # Step 4: Register new session, then invalidate old
        # This ordering prevents a window where user has no valid session
        self.store.update_token(token, new_session)
        # Small delay to ensure any in-flight requests complete
        # before invalidating the old token
        threading.Timer(0.5, self.store.invalidate_old, args=[token]).start()

        return new_session

    def check_elevation(self, token: str) -> bool:
        """Check if session has valid elevation."""
        session = self.store.get(token)
        if not session:
            return False
        if not session.is_elevated:
            return False
        if time.time() > session.elevation_expires:
            session.is_elevated = False
            return False
        return True


def require_elevated(auth_service: AuthenticationService):
    """Decorator that requires elevated session."""
    def decorator(func):
        def wrapper(token: str, *args, **kwargs):
            if not auth_service.check_elevation(token):
                raise PermissionError("Elevated session required")
            return func(token, *args, **kwargs)
        return wrapper
    return decorator


# Application setup
store = SessionStore()
auth = AuthenticationService(store)


@require_elevated(auth)
def admin_delete_user(token: str, target_user: str) -> dict:
    """Admin action: delete a user. Requires elevated session."""
    session = store.get(token)
    if session.role != 'admin':
        raise PermissionError("Admin role required")
    return {'action': 'delete_user', 'target': target_user, 'by': session.user_id}


@require_elevated(auth)
def admin_change_role(token: str, target_user: str, new_role: str) -> dict:
    """Admin action: change user role. Requires elevated session."""
    session = store.get(token)
    if session.role != 'admin':
        raise PermissionError("Admin role required")
    return {'action': 'change_role', 'target': target_user, 'role': new_role, 'by': session.user_id}
